'use strict';
// Builds lucide-subset.js: the Lucide icons VTrade uses, exposed as window.lucide for VCPChat's lucide-adapter.
// usage: node build-subset.cjs <lucide package dir> <lucide-adapter.js> [out file]
const fs = require('node:fs');
const path = require('node:path');

// Icon names as VTrade pages write them: Material-style names go through lucide-adapter's aliases, the rest are Lucide names.
const ICONS = ['add', 'close', 'more_horiz', 'refresh', 'skip-forward', 'pause', 'play_arrow', 'dark_mode', 'light_mode',
    'dashboard', 'link', 'unlink', 'candlestick_chart', 'format_list_bulleted', 'receipt', 'account_balance_wallet',
    'history', 'school', 'smart_toy', 'functions', 'funnel', 'show_chart', 'menu_book', 'layers', 'drag_indicator',
    'save', 'restart_alt', 'inbox', 'progress_activity', 'search', 'edit', 'delete', 'check', 'expand_more', 'expand_less', 'schedule',
    'visibility', 'visibility_off', 'tune', 'maximize-2', 'warning', 'info', 'error', 'check_circle',
    'settings', 'chevron_down', 'download', 'upload', 'sync', 'open_in_new', 'database', 'palette', 'extension', 'dashboard_customize', 'play_circle'];

const [packageDir, adapterFile, outFile = path.join(__dirname, 'lucide-subset.js')] = process.argv.slice(2);
const lucide = require(path.resolve(packageDir));
const version = JSON.parse(fs.readFileSync(path.join(packageDir, 'package.json'), 'utf8')).version;
const aliases = Object.fromEntries([...fs.readFileSync(adapterFile, 'utf8').matchAll(/"([a-z0-9_]+)":\s*"([a-z0-9-]+)"/g)]
    .map(m => [m[1], m[2]]));
const pascal = name => name.split('-').map(part => part.charAt(0).toUpperCase() + part.slice(1)).join('');
const icons = {};
for (const name of ICONS) {
    const lucideName = aliases[name] || name.replaceAll('_', '-');
    const node = lucide.icons[pascal(lucideName)];
    if (!node) throw new Error(`Lucide has no icon for ${name} -> ${lucideName}`);
    icons[pascal(lucideName)] = node;
}
const source = `/**
 * Lucide v${version} icon subset for VTrade (${Object.keys(icons).length} icons). ISC License, see LICENSE.
 * Generated by build-subset.cjs; edit ICONS there and regenerate instead of editing this file.
 */
(() => {
    'use strict';
    const defaultAttributes = { xmlns: 'http://www.w3.org/2000/svg', width: 24, height: 24, viewBox: '0 0 24 24', fill: 'none',
        stroke: 'currentColor', 'stroke-width': 2, 'stroke-linecap': 'round', 'stroke-linejoin': 'round' };
    const build = ([tag, attrs, children]) => {
        const element = document.createElementNS('http://www.w3.org/2000/svg', tag);
        Object.keys(attrs).forEach(name => element.setAttribute(name, String(attrs[name])));
        (children || []).forEach(child => element.appendChild(build(child)));
        return element;
    };
    const icons = ${JSON.stringify(icons)};
    window.lucide = Object.freeze({ icons: Object.freeze(icons),
        createElement: (iconNode, customAttrs = {}) => build(['svg', { ...defaultAttributes, ...customAttrs }, iconNode]) });
})();
`;
fs.writeFileSync(outFile, source);
console.log(`${Object.keys(icons).length} icons from lucide ${version} -> ${outFile}`);
